t.script:
(function() {
    function pad(n) { return n >= 10 ? String(n) : '0' + String(n); }
    function hms(s) {
        s = s > 0 ? s : 0;
        return pad(Math.floor(s / 3600)) + ':' + pad(Math.floor((s % 3600) / 60)) + ':' + pad(s % 60);
    }

    var isCheckedIn = ;
    var checkInUnix = 0;

    function updateClock() {
        var now = new Date();
        var clockEl = document.getElementById('ess_live_clock');

        if (clockEl) {
            if (isCheckedIn && checkInUnix > 0) {
                // Show elapsed time since check-in
                var elapsed = Math.floor(Date.now() / 1000) - checkInUnix;
                clockEl.innerHTML = hms(elapsed);
            } else {
                // Show current wall clock time
                var h = pad(now.getHours());
                var m = pad(now.getMinutes());
                var s = pad(now.getSeconds());
                clockEl.innerHTML = h + ':' + m + ':' + s;
            }
        }

        var days = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
        var months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        var dateEl = document.getElementById('ess_live_date');
        if (dateEl) {
            dateEl.innerHTML = days[now.getDay()] + ', ' + pad(now.getDate()) + ' ' + months[now.getMonth()] + ' ' + now.getFullYear();
        }
    }


    var ELAPSED_SEC_INITIAL = ;
    var HOURS_COMPLETED = parseFloat('') - (ELAPSED_SEC_INITIAL / 3600.0);

    function updateTimer() {
        var elapsed_sec = Math.floor(Date.now() / 1000) - checkInUnix;
        var total_hours = HOURS_COMPLETED + (elapsed_sec / 3600.0);
        var el = document.getElementById('ess_hours_display');
        if (el) el.innerHTML = total_hours.toFixed(2);
    }


    document.addEventListener('DOMContentLoaded', function() {
        updateClock();
        setInterval(updateClock, 1000);


        updateTimer();
        setInterval(updateTimer, 10000);

    });
})();
